import argparse
import json
import sys
import urllib.request
from pathlib import Path

p = argparse.ArgumentParser()
p.add_argument("action", choices=["doctor", "list", "export", "sync-status"])
p.add_argument("--data", required=True)
a = p.parse_args()
config = json.loads(Path(__file__).with_name("config.json").read_text())
rows = json.loads(Path(a.data).read_text())
if a.action == "doctor":
    print(json.dumps({"app": "records", "build": "1.0", "data": str(Path(a.data).resolve()), "rows": len(rows)}))
elif a.action == "list":
    print(json.dumps({"records": rows}))
elif a.action == "export":
    if not config["export_enabled"]:
        print(json.dumps({"error": "export_entitlement_required"})); sys.exit(3)
    if config["remote_export"]:
        try:
            with urllib.request.urlopen(config["service_url"] + "/export", timeout=2) as r:
                print(r.read().decode())
        except Exception as error:
            print(json.dumps({"error": "export_service_unavailable", "detail": str(error)})); sys.exit(4)
    else:
        print(json.dumps({"exported": rows}))
else:
    try:
        with urllib.request.urlopen(config["service_url"] + "/status", timeout=2) as r:
            print(r.read().decode())
    except Exception as error:
        print(json.dumps({"error": "sync_service_unavailable", "detail": str(error)})); sys.exit(4)

